import{_ as a,o as e,c as n,a2 as t}from"./chunks/framework.mRCPFc5l.js";const B=JSON.parse('{"title":"এন্টারপ্রাইজ টপোলজি (Enterprise Topology)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/01_enterprise_topology.md","filePath":"architecture/01_enterprise_topology.md"}'),l={name:"architecture/01_enterprise_topology.md"};function o(r,s,p,c,i,d){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="এন্টারপ্রাইজ-টপোলজি-enterprise-topology" tabindex="-1">এন্টারপ্রাইজ টপোলজি (Enterprise Topology) <a class="header-anchor" href="#এন্টারপ্রাইজ-টপোলজি-enterprise-topology" aria-label="Permalink to &quot;এন্টারপ্রাইজ টপোলজি (Enterprise Topology)&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>নিচে একটি স্ট্যাটিক Mermaid.js ডায়াগ্রাম দেওয়া হয়েছে। যারা ডাইনামিক অ্যানিমেশন (নড়াচড়া করা ছবি) দেখতে চান, তারা <a href="#অ্যানিমেটেড-আর্কিটেকচার-animated-architecture">অ্যানিমেটেড আর্কিটেকচার</a> সেকশনে যান।</p></div><p>এই ডায়াগ্রামটি দেখায় কীভাবে একটি এজ ডিভাইস থেকে &#39;গ্র্যাভিটেশনাল টেলিমিত্রি ডাটা&#39; ইনজেস্ট হয়ে কন্টেইনারাইজড গেটওয়ে, মেসেজ ব্রোকার এবং মেমোরি-ক্যাশড লেয়ার পার হয়ে একটি আল্ট্রা-ফাস্ট কম্পিউট নোডে পৌঁছায়।</p><h2 id="আর্কিটেকচার-ডায়াগ্রাম" tabindex="-1">আর্কিটেকচার ডায়াগ্রাম <a class="header-anchor" href="#আর্কিটেকচার-ডায়াগ্রাম" aria-label="Permalink to &quot;আর্কিটেকচার ডায়াগ্রাম&quot;">​</a></h2><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">graph TD</span></span>
<span class="line"><span style="color:#BABED8;">    %% Styling</span></span>
<span class="line"><span style="color:#BABED8;">    classDef edge fill:#f9f,stroke:#333,stroke-width:2px;</span></span>
<span class="line"><span style="color:#BABED8;">    classDef gateway fill:#bbf,stroke:#333,stroke-width:2px;</span></span>
<span class="line"><span style="color:#BABED8;">    classDef broker fill:#fbb,stroke:#333,stroke-width:2px;</span></span>
<span class="line"><span style="color:#BABED8;">    classDef cache fill:#bfb,stroke:#333,stroke-width:2px;</span></span>
<span class="line"><span style="color:#BABED8;">    classDef compute fill:#fbf,stroke:#333,stroke-width:2px;</span></span>
<span class="line"><span style="color:#BABED8;">    classDef db fill:#ffb,stroke:#333,stroke-width:2px;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">    %% Components</span></span>
<span class="line"><span style="color:#BABED8;">    E[Edge Devices&lt;br/&gt;IoT / Mobile]:::edge --&gt; |Telemetry Data Streams| G[API Gateway&lt;br/&gt;Containerized / Nginx]:::gateway</span></span>
<span class="line"><span style="color:#BABED8;">    </span></span>
<span class="line"><span style="color:#BABED8;">    subgraph Data Ingestion Layer</span></span>
<span class="line"><span style="color:#BABED8;">        G --&gt; |Load Balanced| K1[Kafka Broker 1]:::broker</span></span>
<span class="line"><span style="color:#BABED8;">        G --&gt; |Load Balanced| K2[Kafka Broker 2]:::broker</span></span>
<span class="line"><span style="color:#BABED8;">        K1 &amp; K2 --&gt; |Topic: telemetry_events| K_Cluster((Kafka Cluster)):::broker</span></span>
<span class="line"><span style="color:#BABED8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">    subgraph Processing &amp; Caching</span></span>
<span class="line"><span style="color:#BABED8;">        K_Cluster --&gt; |Consumes Streams| R[Rust/Go Microservices]:::compute</span></span>
<span class="line"><span style="color:#BABED8;">        R --&gt; |Read/Write Hot Data| Redis[(Redis Cache&lt;br/&gt;In-Memory)]:::cache</span></span>
<span class="line"><span style="color:#BABED8;">    end</span></span>
<span class="line"></span>
<span class="line"><span style="color:#BABED8;">    subgraph Storage &amp; Quantum State Tracking</span></span>
<span class="line"><span style="color:#BABED8;">        R --&gt; |Persists State| PG[(PostgreSQL&lt;br/&gt;Relational DB)]:::db</span></span>
<span class="line"><span style="color:#BABED8;">    end</span></span>
<span class="line"><span style="color:#BABED8;">    </span></span>
<span class="line"><span style="color:#BABED8;">    %% Details</span></span>
<span class="line"><span style="color:#BABED8;">    click PG &quot;adrs/0001_postgresql_for_quantum_state_tracking.md&quot; &quot;Why PostgreSQL?&quot;</span></span>
<span class="line"><span style="color:#BABED8;">    click R &quot;adrs/0002_rust_and_go_for_real_time_data_streams.md&quot; &quot;Why Rust/Go?&quot;</span></span></code></pre></div><h3 id="ডায়াগ্রামের-ব্যাখ্যা" tabindex="-1">ডায়াগ্রামের ব্যাখ্যা <a class="header-anchor" href="#ডায়াগ্রামের-ব্যাখ্যা" aria-label="Permalink to &quot;ডায়াগ্রামের ব্যাখ্যা&quot;">​</a></h3><p>১. <strong>Edge Devices</strong>: এখান থেকে সেকেন্ডে হাজার হাজার টেলিমিত্রি ডাটা (যেমন গ্র্যাভিটেশনাল সেন্সর ডেটা) তৈরি হয়। ২. <strong>API Gateway</strong>: এটি মূলত একটি কন্টেইনারাইজড লেয়ার যা প্রথম ধাপে ডেটা রিসিভ করে এবং লোড ব্যালেন্সিং করে। ৩. <strong>Kafka Broker</strong>: যেহেতু ডেটা ভলিউম অনেক বেশি, তাই মেসেজ ব্রোকার হিসেবে Kafka ব্যবহার করা হয়েছে যা কোনো ডেটা না হারিয়ে রিয়েল-টাইমে ডেটা প্রসেসিং সার্ভিসে পাঠায়। ৪. <strong>Rust/Go Microservices</strong>: এগুলো আল্ট্রা-ফাস্ট কম্পিউট নোড, যা কাফকা থেকে ডেটা কনজিউম করে। ৫. <strong>Redis</strong>: ডেটা প্রসেস করার সময় খুব দ্রুত কিছু মেমোরি অ্যাক্সেসের প্রয়োজন হয় (যেমন- সেশন বা স্টেট), যার জন্য Redis ক্যাশ ব্যবহার করা হয়। ৬. <strong>PostgreSQL</strong>: সবশেষে, ডেটার পারসিস্টেন্ট স্টোরেজ এবং জটিল রিলেশনাল কোয়েরির (যেমন- কোয়ান্টাম স্টেট ট্র্যাকিং) জন্য ডেটাবেজ হিসেবে PostgreSQL ব্যবহার করা হয়েছে।</p><h2 id="অ্যানিমেটেড-আর্কিটেকচার-animated-architecture" tabindex="-1">অ্যানিমেটেড আর্কিটেকচার (Animated Architecture) <a class="header-anchor" href="#অ্যানিমেটেড-আর্কিটেকচার-animated-architecture" aria-label="Permalink to &quot;অ্যানিমেটেড আর্কিটেকচার (Animated Architecture)&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>প্লেসহোল্ডার:</strong> এখানে আমাদের ফিউচারিস্টিক অ্যানিমেটেড ডায়াগ্রাম (যেমন- Figma/After Effects থেকে তৈরি করা Isometric .gif) যুক্ত করা হবে।</p></div><p><img src="https://via.placeholder.com/800x400.gif?text=Animated+Architecture+Diagram+Here" alt="Animated Architecture Placeholder"></p><p><em>এই ছবিটিতে ডেটার ফ্লো কীভাবে এক নোড থেকে অন্য নোডে যাচ্ছে তা লাইভ অ্যানিমেশনের মাধ্যমে দেখানো হবে।</em></p>`,11)])])}const h=a(l,[["render",o]]);export{B as __pageData,h as default};
